using System.IO;
using System.Text.Json;
namespace Produktionsplanung.App.Services;
public sealed class AppSettings{public string CompanyName{get;set;}="SolutionCompakt";public string SiteName{get;set;}=string.Empty;public string DefaultBackupDirectory{get;set;}=AppPaths.IsPortableMode?"Backups":AppPaths.BackupsDirectory;public string DefaultExportDirectory{get;set;}=AppPaths.IsPortableMode?"Exports":AppPaths.ExportsDirectory;public bool AutoBackupOnExit{get;set;}=true;public int BackupRetentionCount{get;set;}=10;public string CsvDelimiter{get;set;}=";";public bool IncludeUtf8Bom{get;set;}=true;public DateTime? LastSuccessfulBackupAtLocal{get;set;}public string LastSuccessfulBackupPath{get;set;}=string.Empty;}
public static class AppSettingsService{private static readonly JsonSerializerOptions JsonOptions=new(){WriteIndented=true};public static AppSettings Load(){AppPaths.EnsureDirectories();if(!File.Exists(AppPaths.SettingsPath))return NewDefaults();try{var s=JsonSerializer.Deserialize<AppSettings>(File.ReadAllText(AppPaths.SettingsPath),JsonOptions)??NewDefaults();Normalize(s);return s;}catch{return NewDefaults();}}public static void Save(AppSettings s){AppPaths.EnsureDirectories();Normalize(s);File.WriteAllText(AppPaths.SettingsPath,JsonSerializer.Serialize(s,JsonOptions));}public static string ResolveStoragePath(string? configured,string fallbackRelative){var raw=string.IsNullOrWhiteSpace(configured)?fallbackRelative:configured.Trim();if(Path.IsPathRooted(raw)){if(!AppPaths.IsPortableMode)return raw;var root=Path.GetPathRoot(raw);if(!string.IsNullOrWhiteSpace(root)&&Directory.Exists(root))return raw;return Path.Combine(AppPaths.RootDirectory,fallbackRelative);}return Path.GetFullPath(Path.Combine(AppPaths.RootDirectory,raw));}public static string ToStoredStoragePath(string? path,string fallbackRelative){if(string.IsNullOrWhiteSpace(path))return AppPaths.IsPortableMode?fallbackRelative:Path.Combine(AppPaths.RootDirectory,fallbackRelative);var full=Path.GetFullPath(path.Trim());if(AppPaths.IsPortableMode){var root=Path.GetFullPath(AppPaths.RootDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(full.StartsWith(root,StringComparison.OrdinalIgnoreCase))return Path.GetRelativePath(AppPaths.RootDirectory,full);}return full;}private static AppSettings NewDefaults()=>new(){CompanyName="SolutionCompakt",DefaultBackupDirectory=AppPaths.IsPortableMode?"Backups":AppPaths.BackupsDirectory,DefaultExportDirectory=AppPaths.IsPortableMode?"Exports":AppPaths.ExportsDirectory};private static void Normalize(AppSettings s){var company=s.CompanyName?.Trim()??"";s.CompanyName=string.IsNullOrWhiteSpace(company)||string.Equals(company,"OpsCompact",StringComparison.OrdinalIgnoreCase)||string.Equals(company,"KPI-rai",StringComparison.OrdinalIgnoreCase)?"SolutionCompakt":company;s.SiteName=s.SiteName?.Trim()??"";s.DefaultBackupDirectory=ToStoredStoragePath(s.DefaultBackupDirectory,"Backups");s.DefaultExportDirectory=ToStoredStoragePath(s.DefaultExportDirectory,"Exports");s.BackupRetentionCount=Math.Clamp(s.BackupRetentionCount,1,100);s.CsvDelimiter=string.IsNullOrEmpty(s.CsvDelimiter)?";":s.CsvDelimiter[..1];s.LastSuccessfulBackupPath=s.LastSuccessfulBackupPath?.Trim()??"";}}
